we should prob have a new helper
```
std::optional<SignatureRole>
auxiliaryRole(STObject const& proposedTx, AccountID const& signingFor)
{
    if (signingFor == getInitiator(proposedTx))
        return std::nullopt;
    if (auto const counterparty = proposedTx[~sfCounterparty];
        counterparty && *counterparty == signingFor)
        return SignatureRole::Counterparty;
    if (auto const sponsor = proposedTx[~sfSponsor]; sponsor && *sponsor == signingFor)
        return SignatureRole::Sponsor;
    return std::nullopt;
}

