`isOuterSigningFor` should be modified to include the cosignatures
```
bool
isOuterSigningFor(STObject const& proposedTx, AccountID const& signingFor)
{
    // A contribution for the proposed transaction itself: its initiator
    // (Account or Delegate), or a Counterparty / Sponsor co-signature.
    // Not an inner Batch participant — those go in sfBatchSigners.
    return signingFor == getInitiator(proposedTx) ||
        auxiliaryRole(proposedTx, signingFor).has_value();
}
